('ec000011-0000-0000-0000-000000000011', 'fd000017-0000-0000-0000-000000000017', 'Bánh mì thịt nướng', 'Bánh mì Việt Nam nhồi thịt nguội nướng và rau gia vị', 15, 10, 25, 1, 'Easy', 'Breakfast', 25000, '["Bước 1: Nướng bánh mì giòn trên lửa than hoặc lò nướng.", "Bước 2: Thịt nguội nướng trên chảo nóng với chút dầu đến khi vàng.", "Bước 3: Cắt bánh mì đôi, phết sốt mayonnaise và pate nếu có.", "Bước 4: Xếp thịt nguội, dưa leo, rau răm, hành tây vào bánh mì."]', 'https://images.unsplash.com/photo-1509722747041-616f39b57569?w=400', NULL, true, now()),
('ec000012-0000-0000-0000-000000000012', 'fd000018-0000-0000-0000-000000000018', 'Gỏi cuốn tôm thịt', 'Cuốn bánh tráng trong mỏng nhân tôm thịt luộc và rau xanh', 20, 15, 35, 1, 'Easy', 'Lunch', 35000, '["Bước 1: Luộc tôm và thịt heo chín, để nguội và thái lát.", "Bước 2: Ngâm bánh tráng trong nước ấm cho mềm.", "Bước 3: Đặt nhân tôm, thịt, bún, rau thơm, xà lách lên bánh tráng.", "Bước 4: Cuộn chặt tay, chấm với nước mắm chua ngọt."]', 'https://images.unsplash.com/photo-1562967916-eb82221dfb44?w=400', NULL, true, now()),
('ec000013-0000-0000-0000-000000000013', 'fd000025-0000-0000-0000-000000000025', 'Xôi xéo giò lụa', 'Xôi nếp dẻo phủ nước xôi vàng ươm kèm giò lụa', 30, 45, 75, 2, 'Medium', 'Breakfast', 35000, '["Bước 1: Vo gạo nếp, ngâm qua đêm.", "Bước 2: Nấu xôi bằng hấp hoặc nồi cơm điện.", "Bước 3: Xào đậu xanh nấu chín rồi nghiền nát.", "Bước 4: Pha nước xôi với dầu ăn và hành phi. Đổ xôi ra đĩa, rưới nước xôi, đặt giò lụa."]', 'https://images.unsplash.com/photo-1589115018-17b7b3da4d3a?w=400', NULL, true, now()),
('ec000014-0000-0000-0000-000000000014', 'fd000032-0000-0000-0000-000000000032', 'Overnight oats với berries', 'Yến mạch ngâm qua đêm với sữa chua và trái cây', 5, 0, 5, 1, 'Easy', 'Breakfast', 35000, '["Bước 1: Cho yến mạch, sữa hạnh nhân, sữa chua vào jar.", "Bước 2: Thêm chút mật ong và vanilla.", "Bước 3: Đậy nắp, lắc đều và để trong tủ lạnh qua đêm.", "Bước 4: Sáng hôm sau, trang trí với berries tươi, hạt chia và granola."]', 'https://images.unsplash.com/photo-1517673400267-0251440c45dc?w=400', NULL, true, now()),
('ec000015-0000-0000-0000-000000000015', 'fd000033-0000-0000-0000-000000000033', 'Grilled chicken với rau nướng', 'Ức gà nướng than thơm lừng với rau củ nướng', 10, 20, 30, 1, 'Easy', 'Lunch', 55000, '["Bước 1: Ướp ức gà với tỏi, rosemary, muối, tiêu và dầu olive.", "Bước 2: Để yên trong 15-30 phút cho ngấm.", "Bước 3: Nướng ức gà trên than hoặc lò nướng ở 200 độ C trong 20 phút.", "Bước 4: Nướng kèm rau củ như cà chua,ớt chuông, cà rốt với dầu olive và thảo mộc."]', 'https://images.unsplash.com/photo-1532550907401-a500c9a57435?w=400', NULL, true, now()),
('ec000016-0000-0000-0000-000000000016', 'fd000036-0000-0000-0000-000000000036', 'Quinoa salad với sốt tahini', 'Quinoa trắng xanh cùng rau củ tươi và sốt tahini', 15, 0, 15, 1, 'Easy', 'Lunch', 45000, '["Bước 1: Nấu quinoa theo hướng dẫn trên bao bì, để nguội.", "Bước 2: Rau củ rửa sạch: cà chua, dưa leo, hành tây, rau mầm.", "Bước 3: Pha sốt tahini với nước cốt chanh, tỏi băm, muối.", "Bước 4: Trộn quinoa với rau củ, rưới sốt tahini và trang trí hạt é."]', 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?w=400', NULL, true, now()),
('ec000017-0000-0000-0000-000000000017', 'fd000037-0000-0000-0000-000000000037', 'Acai smoothie bowl', 'Bát sinh tố đông đặc với acai và topping', 10, 5, 15, 1, 'Easy', 'Breakfast', 55000, '["Bước 1: Đông đá chuối và quả mâm xôi trước.", "Bước 2: Cho acai đông lạnh, chuối, sữa dừa vào blender.", "Bước 3: Xay nhuyễn đến khi hỗn hợp đặc mịn.", "Bước 4: Đổ ra bowl, trang trí granola, dừa nạo, hạt chia, trái cây tươi."]', 'https://images.unsplash.com/photo-1590301157890-4810ed352733?w=400', NULL, true, now()),
('ec000018-0000-0000-0000-000000000018', 'fd000049-0000-0000-0000-000000000049', 'Cơm gà Hainan', 'Cơm trắng thơm mềm ăn với gà luộc và nước mắm gừng', 20, 30, 50, 2, 'Medium', 'Lunch', 55000, '["Bước 1: Gà luộc trong nước dùng nóng với gừng và hành tím, đến khi chín mềm.", "Bước 2: Vớt gà ra, ngâm nước đá cho da giòn, cắt miếng.", "Bước 3: Nấu cơm với nước dùng gà và chút mỡ gà.", "Bước 4: Pha nước chấm gừng với nước mắm, đường, tiêu. Ăn kèm rau dưa."]', 'https://images.unsplash.com/photo-1604503468506-a8da13d82791?w=400', NULL, true, now()),
('ec000019-0000-0000-0000-000000000019', 'fd000020-0000-0000-0000-000000000020', 'Cơm rang dưa bò', 'Cơm rang khô rời với thịt bò xào và dưa cải', 10, 15, 25, 1, 'Easy', 'Lunch', 45000, '["Bước 1: Nấu cơm nguội (tốt nhất là cơm qua đêm).", "Bước 2: Bò thái mỏng, ướp gia vị, xào nhanh trên lửa lớn.", "Bước 3: Phi trứng rồi đánh tơi, để riêng.", "Bước 4: Rang cơm với dầu, thêm bò, dưa cải chua, trứng, nêm gia vị, rang đều tay."]', 'https://images.unsplash.com/photo-1603133872878-684f208fb84b?w=400', NULL, true, now()),
('ec000020-0000-0000-0000-000000000020', 'fd000047-0000-0000-0000-000000000047', 'Gỏi đu đủ khô bò', 'Đu đủ xanh bào sợi trộn khô bò giòn rụm', 15, 0, 15, 1, 'Easy', 'Lunch', 30000, '["Bước 1: Đu đủ xanh gọt vỏ, bào sợi mỏng.", "Bước 2: Khô bò xé sợi nhỏ, rang sơ trên chảo nóng.", "Bước 3: Pha nước trộn gỏi: nước mắm, đường, chanh, tỏi, ớt.", "Bước 4: Trộn đu đủ với nước trộn gỏi, thêm đậu phộng rang, khô bò và rau răm."]', 'https://images.unsplash.com/photo-1559314809-0d155014e29e?w=400', NULL, true, now())
