-- Keep recipe artwork aligned with its linked catalog food without overwriting
-- an image explicitly configured for the recipe.
UPDATE recipes AS r
SET "ImageUrl" = f."ImageUrl"
FROM foods AS f
WHERE r."FoodId" = f."Id"
  AND (r."ImageUrl" IS NULL OR btrim(r."ImageUrl") = '')
  AND f."ImageUrl" IS NOT NULL
  AND btrim(f."ImageUrl") <> '';

UPDATE recipes
SET "ImageUrl" = 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=400'
WHERE "ImageUrl" IS NULL OR btrim("ImageUrl") = '';

COMMIT;
